'use strict';
// MS13c scratch (from MS13a's work-census-all.js): the ladder positions of the MS13a census, under the loaded chain engine.
// Run it with MS13C_CHAIN=git:4aa3d11 (the base engine: singleton forcing finders) to dump the positions at which the chain
// group is reached by a ladder solve of the six propagated puzzles of H.randomStatesWithKnownSolution(m, rng(77003), 24),
// exactly the inputs of MS13a's census (docs/difficulty-v3/evidence/MS13a/census-all/), as JSON that the activation census
// (census-run.js) reads: nothing is regenerated by the tree's engine, so the positions are the old ones.
// Usage (from generator/): node tests/artifacts/difficulty-v3/MS13c/census-dump.js <out dir> [id,id,...]
const fs = require('fs');
const path = require('path');
const SG = require('./load.js');
const H = SG.techHelper;
const MAX_STEPS = 3000;

function applyFinding(model, state, finding) {
  for (const p of finding.placements) if (!SG.constraints.assign(model, state, p[0], p[1])) return false;
  for (const e of finding.eliminations) if (!SG.constraints.eliminate(model, state, e[0], e[1])) return false;
  return SG.constraints.propagate(model, state);
}

function ladderPositions(model, start, ctx, techs) {
  const positions = [];
  const state = SG.model.cloneState(start);
  let steps = 0;
  let outcome = 'solved';
  while (state.unsolvedCount > 0) {
    if (steps >= MAX_STEPS) { outcome = 'step cap'; break; }
    let fired = null;
    for (const tech of techs) {
      if (tech.id === 'xyChain') positions.push({ step: steps, state: SG.model.cloneState(state) });
      fired = tech.find(model, state, ctx);
      if (fired) break;
    }
    if (!fired) { outcome = 'stuck'; break; }
    if (!applyFinding(model, state, fired)) { outcome = 'contradiction'; break; }
    steps++;
  }
  return { positions, steps, outcome };
}

const outDir = process.argv[2];
if (!outDir) throw new Error('usage: census-dump.js <out dir> [id,id,...]');
const ids = process.argv[3] ? process.argv[3].split(',') : SG.testkit.VARIANT_IDS;
fs.mkdirSync(outDir, { recursive: true });
ids.forEach((id) => {
  const t0 = Date.now();
  const model = H.model(id);
  const ctx = SG.techniques.createContext(model, { assumeUniqueness: true });
  const techs = SG.techniques.list().filter((t) => SG.techniques.appliesTo(t, model.variantId));
  const items = H.randomStatesWithKnownSolution(model, SG.testkit.rng.create(77003), 24);
  const propagated = items.filter((i) => i.kind === 'propagated');
  const out = { id, engine: process.env.MS13C_CHAIN || 'tree', puzzles: propagated.length, positions: [], outcomes: [] };
  propagated.forEach((item, p) => {
    const solve = ladderPositions(model, item.state, ctx, techs);
    out.outcomes.push(solve.outcome);
    solve.positions.forEach((pos) => out.positions.push({ puzzle: p, step: pos.step,
      candidates: Array.from(pos.state.candidates), value: Array.from(pos.state.value) }));
  });
  fs.writeFileSync(path.join(outDir, id + '.json'), JSON.stringify(out).replace(/\n/g, '\r\n') + '\r\n', 'utf8');
  console.log(id + ': ' + out.puzzles + ' puzzles, ' + out.positions.length + ' positions, outcomes ' + out.outcomes.join(',') + ', ' +
    ((Date.now() - t0) / 1000).toFixed(1) + ' s (' + out.engine + ')');
});
